const $=id=>document.getElementById(id);let tenant='care-beyond';
async function api(path,method='GET',value){const r=await fetch('api/admin/'+path+(path.includes('?')?'&':'?')+'tenant='+encodeURIComponent(tenant),{method,headers:value?{'Content-Type':'application/json'}:{},body:value?JSON.stringify(value):undefined});let data;try{data=await r.json();}catch{throw new Error('Connect the Hostinger backend to use the knowledge manager.');}if(!r.ok)throw new Error(data.error||'Request could not complete.');return data;}
function item(title,detail){const e=document.createElement('div'),s=document.createElement('span');s.textContent=title;const small=document.createElement('small');small.textContent=detail;s.append(small);e.append(s);return e;}
async function refresh(){const data=await api('status');$('loginForm').hidden=true;$('adminControls').hidden=false;$('knowledgeControls').hidden=false;$('adminStatus').textContent='Signed in. Each provider has its own document knowledge base.';
  $('tenantSelect').replaceChildren();for(const p of data.tenants){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;o.selected=p.id===tenant;$('tenantSelect').append(o);}
  $('integrationStatus').replaceChildren();for(const text of [`AI ${data.aiEnabled?'connected':'not connected'}`,`Email ${data.emailEnabled?'configured — delivery test needed':'not connected'}`,`${data.usage.daily||0} AI calls reserved today`]){const s=document.createElement('span');s.textContent=text;$('integrationStatus').append(s);}
  $('documentList').replaceChildren();if(!data.documents.length)$('documentList').append(item('No documents uploaded yet','The curated website and NDIS knowledge remains available.'));
  for(const d of data.documents){const e=item(d.title,`${d.chunkCount} sections · Reviewed ${d.reviewedAt}`),b=document.createElement('button');b.className='text-button';b.textContent='Remove';b.type='button';b.addEventListener('click',async()=>{try{await api('documents','DELETE',{id:d.id});await refresh();}catch(error){$('uploadStatus').textContent=error.message;}});e.append(b);$('documentList').append(e);}
  $('sharedList').replaceChildren();for(const d of data.shared)$('sharedList').append(item(d.title,`Reviewed ${d.reviewedAt}`));
}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('login','POST',{password:$('adminPassword').value});$('adminPassword').value='';await refresh();}catch(error){$('adminStatus').textContent=error.message;}});
$('tenantSelect').addEventListener('change',async e=>{tenant=e.target.value;try{await refresh();}catch(error){$('adminStatus').textContent=error.message;}});
$('logout').addEventListener('click',async()=>{try{await api('logout','POST',{});}finally{location.reload();}});
$('uploadForm').addEventListener('submit',async e=>{e.preventDefault();const file=$('knowledgeFile').files[0];if(!file)return;if(file.size>5000000){$('uploadStatus').textContent='Please choose a file smaller than 5 MB.';return;}const button=e.target.querySelector('button');button.disabled=true;$('uploadStatus').textContent='Reading and adding the document…';
  try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const result=await api('documents','POST',{fileName:file.name,base64,publishConsent:$('documentConsent').checked});$('uploadStatus').textContent=`${result.title} added. ${result.chunkCount} sections are ready for answers.`;e.target.reset();await refresh();}catch(error){$('uploadStatus').textContent=error.message;}finally{button.disabled=false;}
});
$('syncWebsite').addEventListener('click',async()=>{if(!$('websiteConsent').checked){$('syncStatus').textContent='Approve the website information before importing it.';return;}$('syncWebsite').disabled=true;$('syncStatus').textContent='Reading the configured provider website…';try{const result=await api('sync','POST',{publishConsent:true});$('syncStatus').textContent=`${result.imported} website pages imported.`;await refresh();}catch(error){$('syncStatus').textContent=error.message;}finally{$('syncWebsite').disabled=false;}});
refresh().catch(()=>{$('adminStatus').textContent='Sign in with the ADMIN_PASSWORD configured on Hostinger. The private static review does not connect to a backend.';});
